INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass NFC immer für große Distanzen geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur kurze Reichweite"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich NFC für ein IT-System auswähle?', 3, '[{"text": "Reichweite", "correct": true, "because": "Bestimmt Einsatz"}, {"text": "Schnellste Installation", "correct": false, "because": "Funktion zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat NFC?', 5, '[{"text": "Kurze Reichweite", "correct": true, "because": "Bis ca. 10 cm"}, {"text": "Kontaktlose Kommunikation", "correct": true, "because": "Drahtlos"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Geringe Datenrate"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) NFC arbeitet mit 13,56 MHz. b) Es ist für Langstrecken geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kurzreichweite"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich NFC für ein IT-System plane?', 4, '[{"text": "Reichweite", "correct": false, "because": "Bestimmt Einsatz"}, {"text": "Sicherheitsfunktionen", "correct": false, "because": "Schützen Daten"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob NFC nur für Bezahlsysteme genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Datenübertragung"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit NFC in einem IT-System?', 3, '[{"text": "Kontaktlose Kommunikation", "correct": true, "because": "Schnelle Datenübertragung"}, {"text": "Schnellste Installation", "correct": false, "because": "Funktion zählt"}, {"text": "Große Reichweite", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind bei NFC entscheidend?', 5, '[{"text": "Kurze Reichweite", "correct": true, "because": "Bis ca. 10 cm"}, {"text": "Sicherheit", "correct": true, "because": "Schützt Daten"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) NFC nutzt RFID-Technologie. b) Es hat eine Reichweite von mehreren Metern. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Reichweite bis 10 cm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um NFC effektiv einzusetzen?', 4, '[{"text": "NFC-Tags", "correct": false, "because": "Ermöglichen Kommunikation"}, {"text": "Sicherheitsprotokolle", "correct": false, "because": "Schützen Daten"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist NFC immer schneller als Bluetooth?', 2, '[{"text": "Nein", "correct": true, "because": "Geringere Datenrate"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet NFC?', 4, '[{"text": "Schnelle Verbindung", "correct": true, "because": "Sofortiger Kontakt"}, {"text": "Einfache Bedienung", "correct": true, "because": "Kontaktlos"}, {"text": "Hohe Reichweite", "correct": false, "because": "Kurzreichweite"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass NFC nur für Smartphones geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Karten, Geräte"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um NFC für ein IT-System effektiv zu nutzen?', 3, '[{"text": "Sicherheitsmaßnahmen", "correct": true, "because": "Schützen Daten"}, {"text": "Schnellste Hardware", "correct": false, "because": "Funktion wichtiger"}, {"text": "Bunte Tags", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) NFC hat eine geringe Reichweite. b) Es ist immer unsicher.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei NFC?', 5, '[{"text": "Reichweite", "correct": true, "because": "Bestimmt Einsatz"}, {"text": "Datenrate", "correct": true, "because": "Beeinflusst Leistung"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich NFC für ein IT-System plane?', 3, '[{"text": "Sicherheitsprotokolle", "correct": false, "because": "Schützen Daten"}, {"text": "Kompatibilität", "correct": false, "because": "Sichert Funktion"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist NFC immer für große Datenmengen geeignet?', 3, '[{"text": "Nein", "correct": true, "because": "Geringe Datenrate"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob NFC nur für Bezahlsysteme genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Datenübertragung"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für NFC?', 4, '[{"text": "Kurze Reichweite", "correct": true, "because": "Kern der Technologie"}, {"text": "Schnellste Installation", "correct": false, "because": "Funktion zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
